public final class NonPokemonBatch119Test {
    static final UUID A=GeneratedRuleBatch8Test.A,B=GeneratedRuleBatch8Test.B;
    static final String CHAOS="xy10_en_094",PARALLEL="xy8_en_145",REVERSE="xy9_en_110";
    static final List<String> IDS=List.of(CHAOS,PARALLEL,REVERSE);
    static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
    static void reject(Runnable r){GeneratedRuleBatch8Test.reject(r);}
    static UUID other(UUID p){return p.equals(A)?B:A;}
    static TrainerProfile profile(String id){return NonPokemonBatch2Test.DATA.trainer(id).orElseThrow();}
    static CardInstance hand(ServerMatch m,UUID p,String id){return DynamicPassiveModifierTest.hand(m,p,id);}
    static UUID active(ServerMatch m,UUID p){return m.activePokemonView(p).pokemonId();}
    static GeneratedRuleBatch28Test.Config config(String id){var c=new GeneratedRuleBatch28Test.Config();c.trainer=profile(id);c.ownTypes=Set.of(EnergyType.GRASS);c.defenderTypes=Set.of(EnergyType.METAL);return c;}
    static ServerMatch game(String id){return GeneratedRuleBatch28Test.fixture(config(id));}
    static void play(ServerMatch m,UUID p,UUID first){m.playTrainer(p,hand(m,p,"trainer").instanceId(),null,first);}
    static void turn(ServerMatch m,UUID p){if(!m.currentPlayer().equals(p))m.endTurn(m.currentPlayer());}
    static ServerMatch aiGame(String id){var c=config(id);c.attack=GeneratedRuleBatch8Test.hit(200,false);c.defenderAttack=c.attack;return GeneratedRuleBatch28Test.fixture(c);}
    public static void main(String[] args){directions();chaos();damage();benchDamage();sourceAttribution();parallel();replacement();hpCorrection();ai();schema();System.out.println("NonPokemonBatch119Test passed: Chaos Tower, Parallel City and Reverse Valley both players/orientations; explicit pre-play direction, fixed public orientation and same-name/quota/authority gates; all conditions and live type damage timing including dual types/own and opposing Bench; actual source protection; one-sided bench limits, owner-chosen discards without Prizes, Sky Field ordered replacement, Swell nonactivation, removal and four AI difficulties");}
    static void directions(){for(String id:IDS)for(UUID p:List.of(A,B))for(UUID first:List.of(A,B)){
        var m=game(id);turn(m,p);var card=hand(m,p,"trainer");var before=m.clientView(p);var rng=m.randomTranscript();reject(()->m.playTrainer(p,card.instanceId(),null));reject(()->m.playTrainer(p,card.instanceId(),null,UUID.randomUUID()));reject(()->m.playTrainer(other(p),card.instanceId(),null,first));check(before.equals(m.clientView(p))&&rng.equals(m.randomTranscript()),"Invalid orientation changed state");
        var session=MatchSession.multiplayer(m,A,B);var choices=session.view(p,p).options().stream().filter(o->o.cardKeys().contains("hand:"+card.instanceId())&&o.type()==ActionType.TRAINER).toList();check(choices.size()==2&&choices.stream().allMatch(o->o.labelZh().contains("我方：")&&o.labelZh().contains("对方：")),"Both orientations missing or unlabeled");var selected=choices.stream().filter(o->o.cardKeys().contains("stadium-first:"+(p.equals(first)?"SELF":"OPPONENT"))).findFirst().orElseThrow();session.submit(p,p,session.view(p,p).revision(),selected.index());check(first.equals(m.stadiumFirstSide())&&m.clientView(p).stadium().equals(card),"Chosen orientation/card identity lost");for(UUID viewer:List.of(A,B)){String detail=MatchRegionModel.from(session.view(viewer,viewer)).zone("stadium").cards().getFirst().detailZh();check(detail.contains("我方："+profile(id).stadiumSideLabel(viewer.equals(first)))&&detail.contains("对方："+profile(id).stadiumSideLabel(!viewer.equals(first))),"Public orientation reversed for viewer");}
        reject(()->m.playTrainer(p,card.instanceId(),null,other(first)));check(first.equals(m.stadiumFirstSide()),"Replayed card rotated Stadium");turn(m,other(p));check(!m.canPlayTrainer(other(p),hand(m,other(p),"trainer").instanceId(),null),"Opposite orientation bypassed same-name rule");m.discardStadiumByEffect(other(p));check(m.stadiumFirstSide()==null,"Removed Stadium retained direction");
    }}
    static void chaos(){for(UUID actor:List.of(A,B))for(UUID first:List.of(A,B))for(SpecialCondition status:SpecialCondition.values()){
        var m=game(CHAOS);turn(m,actor);for(UUID p:List.of(A,B))EventTargetBindingTest.field(m).applySpecialCondition(p,status,status==SpecialCondition.POISONED?4:BattlefieldState.defaultCheckupCounters(status));play(m,actor,first);
        for(UUID p:List.of(A,B)){boolean immune=p.equals(first)?Set.of(SpecialCondition.CONFUSED,SpecialCondition.POISONED).contains(status):Set.of(SpecialCondition.ASLEEP,SpecialCondition.PARALYZED).contains(status);check(m.activePokemonView(p).conditions().contains(status)!=immune,"Chaos Tower cured wrong condition/side "+status);if(m.activePokemonView(p).conditions().contains(status))EventTargetBindingTest.field(m).clearSpecialConditions(p,active(m,p),Set.of(status));m.applySpecialConditionByEffect(actor,p,status,status==SpecialCondition.POISONED?4:BattlefieldState.defaultCheckupCounters(status));check(m.activePokemonView(p).conditions().contains(status)!=immune,"Chaos Tower failed later immunity "+status);}
        m.discardStadiumByEffect(actor);for(UUID p:List.of(A,B)){if(m.activePokemonView(p).conditions().contains(status))EventTargetBindingTest.field(m).clearSpecialConditions(p,active(m,p),Set.of(status));m.applySpecialConditionByEffect(actor,p,status,status==SpecialCondition.POISONED?4:BattlefieldState.defaultCheckupCounters(status));check(m.activePokemonView(p).conditions().contains(status),"Removed Tower still prevented condition");}
    }}
    static void damage(){for(String id:List.of(PARALLEL,REVERSE))for(UUID actor:List.of(A,B))for(UUID first:List.of(A,B))for(EnergyType type:List.of(EnergyType.GRASS,EnergyType.FIRE,EnergyType.WATER,EnergyType.DARKNESS,EnergyType.METAL,EnergyType.PSYCHIC))for(boolean weak:List.of(false,true)){
        var c=config(id);c.ownTypes=Set.of(type);c.defenderTypes=Set.of(EnergyType.METAL);c.weakness=weak;var m=GeneratedRuleBatch28Test.fixture(c);turn(m,actor);play(m,actor,first);turn(m,A);m.attack(A,"hit");int dealt=id.equals(PARALLEL)&&!A.equals(first)&&Set.of(EnergyType.GRASS,EnergyType.FIRE,EnergyType.WATER).contains(type)?-20:id.equals(REVERSE)&&!A.equals(first)&&type==EnergyType.DARKNESS?10:0;int received=id.equals(REVERSE)&&B.equals(first)?-10:0;check(m.lastAttack().finalDamage()==(100+dealt)*(weak?2:1)+received,"Directional damage/type/Weakness ordering: "+id+" "+type+" "+first+" got "+m.lastAttack().finalDamage());
    }var c=config(PARALLEL);c.ownTypes=Set.of(EnergyType.GRASS,EnergyType.FIRE);var m=GeneratedRuleBatch28Test.fixture(c);play(m,A,B);m.attack(A,"hit");check(m.lastAttack().finalDamage()==80,"Dual-type attacker reduced twice");}
    static void benchDamage(){for(String id:List.of(PARALLEL,REVERSE))for(UUID first:List.of(A,B)){
        var c=config(id);c.ownTypes=Set.of(id.equals(PARALLEL)?EnergyType.GRASS:EnergyType.DARKNESS);c.attack=DeckDiscardTriggeredAbilityTest.attack(100,"{\"type\":\"bench_damage\",\"target\":\"OWN_BENCH\",\"amount\":40},{\"type\":\"bench_damage\",\"target\":\"OPPONENT_BENCH\",\"amount\":40}");var m=GeneratedRuleBatch28Test.fixture(c);play(m,A,first);m.attack(A,"hit");NonPokemonBatch103Test.settle(m);int own=id.equals(PARALLEL)&&first.equals(B)?20:40;int opposing=id.equals(PARALLEL)&&first.equals(B)?20:id.equals(REVERSE)&&first.equals(B)?30:40;check(m.benchPokemonView(A).getFirst().damage()==own&&m.benchPokemonView(B).getFirst().damage()==opposing,"Bench/own damage scope or Reverse Valley Active-only bonus wrong");
    }}
    static void sourceAttribution(){for(UUID controller:List.of(A,B)){
        var m=game(REVERSE);turn(m,controller);EventTargetBindingTest.field(m).addProtection(A,B,active(m,B),new ProtectionEffect(new EffectProtection(EffectProtection.Source.TRAINER,EffectProtection.Relation.OPPONENT,EffectProtection.Scope.EFFECTS_ONLY),ContinuousEffect.Expiry.LEAVES_PLAY));play(m,controller,B);turn(m,A);m.attack(A,"hit");check(m.lastAttack().finalDamage()==(controller.equals(A)?100:90),"Direction replaced actual Stadium controller in Trainer protection");
    }}
    static void fill(ServerMatch m,UUID p,int size){while(m.benchPokemonView(p).size()<size){if(m.privateView(p).hand().stream().noneMatch(c->c.definitionId().equals("basic")))m.drawCardsByEffect(p,p,3);m.playBasicPokemonToBench(p,hand(m,p,"basic").instanceId());}}
    static ServerMatch twoStadiums(TrainerProfile old,TrainerProfile next){
        var defs=new ArrayList<CardDefinition>();for(String id:List.of("basic","trainer","stadium","energy"))defs.add(new CardDefinition(id,id,id.equals("basic")?CardCategory.POKEMON:id.equals("energy")?CardCategory.ENERGY:CardCategory.TRAINER,Set.of("trainer","stadium").contains(id)?TrainerCategory.STADIUM:TrainerCategory.NONE,"H",Set.of("international"),id.equals("basic"),id.equals("energy"),60,Map.of(),EffectSupport.SUPPORTED,null));
        var combat=new CombatCatalog(Map.of("basic",new PokemonProfile(1000,0,null,null,0,null,0,1,List.of(GeneratedRuleBatch8Test.hit(100,false)),List.of(),EnergyType.GRASS)),Map.of("energy",EnergyType.GRASS),Map.of("stadium",old,"trainer",next),Map.of());
        for(int seed=0;seed<100;seed++){var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++){String id=i%6<3?"basic":i%6==3?"trainer":i%6==4?"stadium":"energy";cards.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,id));}decks.add(cards);}var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(x->x.definitionId().equals("basic")).count()<2))continue;OpeningTestSupport.complete(m,A,B,1);m.drawCardsByEffect(A,A,30);m.drawCardsByEffect(A,B,30);m.endTurn(A);m.endTurn(B);return m;}throw new AssertionError("No two-Stadium fixture");
    }
    static void parallel(){for(UUID actor:List.of(A,B))for(UUID first:List.of(A,B)){
        var m=twoStadiums(DynamicPassiveModifierTest.plainStadium(),profile(PARALLEL));fill(m,A,5);m.endTurn(A);fill(m,B,5);turn(m,actor);int prizes=m.privateView(A).prizes().size()+m.privateView(B).prizes().size();play(m,actor,first);check(m.benchLimit(first)==3&&m.benchLimit(other(first))==5,"Parallel City changed both capacities");var q=m.toolOverflowPrompt();check(q!=null&&q.owner().equals(first),"Wrong bench owner prompted");reject(()->m.endTurn(actor));reject(()->m.discardOverflowTool(other(first),q.id(),q.tools().getFirst().instanceId()));for(int i=0;i<2;i++){var step=m.toolOverflowPrompt();check(step!=null&&step.owner().equals(first),"Parallel overflow ownership changed");m.discardOverflowTool(first,step.id(),step.tools().getLast().instanceId());}check(m.toolOverflowPrompt()==null&&m.benchPokemonView(first).size()==3&&m.benchPokemonView(other(first)).size()==5&&m.privateView(A).prizes().size()+m.privateView(B).prizes().size()==prizes,"Bench discard removed wrong side or gave Prizes");reject(()->m.discardOverflowTool(first,q.id(),q.tools().getFirst().instanceId()));turn(m,first);check(!m.canPlayBasicPokemonToBench(first,"basic"),"Parallel capacity not enforced later");m.discardStadiumByEffect(first);check(m.benchLimit(first)==5&&m.canPlayBasicPokemonToBench(first,"basic"),"Capacity not restored after removal");
    }}
    static void replacement(){for(UUID oldOwner:List.of(A,B))for(UUID first:List.of(A,B)){
        var m=twoStadiums(profile("xy6_en_089"),profile(PARALLEL));turn(m,oldOwner);m.playTrainer(oldOwner,hand(m,oldOwner,"stadium").instanceId(),null);fill(m,oldOwner,8);m.endTurn(oldOwner);fill(m,other(oldOwner),8);play(m,other(oldOwner),first);for(UUID p:List.of(first,other(first))){int count=p.equals(first)?5:3;for(int i=0;i<count;i++){var q=m.toolOverflowPrompt();check(q!=null&&q.owner().equals(p),"Sky Field replacement did not process restricted side first");m.discardOverflowTool(p,q.id(),q.tools().getLast().instanceId());}}check(m.toolOverflowPrompt()==null&&m.benchPokemonView(first).size()==3&&m.benchPokemonView(other(first)).size()==5,"Sky Field replacement capacities wrong");
    }for(String id:IDS){var m=twoStadiums(profile("sm12_en_187"),profile(id));m.playTrainer(A,hand(m,A,"stadium").instanceId(),null);fill(m,A,5);m.endTurn(A);fill(m,B,5);EventTargetBindingTest.field(m).applySpecialCondition(B,SpecialCondition.POISONED,1);play(m,B,B);check(m.clientView(B).stadium()==null&&m.stadiumFirstSide()==null&&m.toolOverflowPrompt()==null&&m.activePokemonView(B).conditions().contains(SpecialCondition.POISONED)&&m.benchPokemonView(B).size()==5,"Chaotic Swell allowed new directional Stadium to become active");}}
    static void hpCorrection(){for(UUID first:List.of(A,B))for(boolean discardLethal:List.of(false,true)){
        var bonus=DynamicPassiveModifierTest.trainer("STADIUM","{\"type\":\"hit_points_modifier\",\"target\":\"ALL_OWN_POKEMON\",\"amount\":30},{\"type\":\"hit_points_modifier\",\"target\":\"ALL_OPPONENT_POKEMON\",\"amount\":30}");var m=twoStadiums(bonus,profile(PARALLEL));m.playTrainer(A,hand(m,A,"stadium").instanceId(),null);fill(m,A,5);m.endTurn(A);fill(m,B,5);var lethal=m.benchPokemonView(first).getFirst();var physical=EventTargetBindingTest.field(m).topCard(first,lethal.pokemonId());m.placeDamageCountersByEffect(B,first,lethal.pokemonId(),60);m.placeDamageCountersByEffect(B,first,lethal.pokemonId(),41);int prizes=m.privateView(other(first)).prizes().size();play(m,B,first);check(m.toolOverflowPrompt()!=null&&m.benchPokemonView(first).size()==5&&m.privateView(other(first)).prizes().size()==prizes,"HP knockout preceded mandatory Parallel bench discards");
        for(int i=0;i<2;i++){var q=m.toolOverflowPrompt();var chosen=discardLethal&&i==0?physical:q.tools().getLast();m.discardOverflowTool(first,q.id(),chosen.instanceId());}NonPokemonBatch103Test.settle(m);check(m.benchPokemonView(first).size()==(discardLethal?3:2)&&m.privateView(other(first)).prizes().size()==prizes-(discardLethal?0:1),"HP knockout did not resume after mandatory bench discards");
    }}
    static void ai(){for(String id:IDS)for(var difficulty:AiDifficulty.values()){
        var m=aiGame(id);if(id.equals(CHAOS))EventTargetBindingTest.field(m).applySpecialCondition(A,SpecialCondition.POISONED,1);
        var s=MatchSession.multiplayer(m,A,B);var input=AiPracticeScenarios.view(s,A);var snap=input.snapshot();var options=snap.options().stream().filter(o->o.type()==ActionType.TRAINER).toList();var limited=new MatchSession.Snapshot(snap.revision(),snap.practice(),snap.controllableSeats(),snap.game(),options,snap.cardNames(),snap.publicCues(),snap.attackBlockZh(),snap.guidance(),snap.events(),snap.computer());var view=new AiView(limited,input.cards(),input.energy(),input.deck(),input.turn());var decision=AiPolicy.choose(view,10,Set.of(),difficulty).orElseThrow();var selected=options.stream().filter(o->o.index()==decision.option()).findFirst().orElseThrow();check(selected.cardKeys().contains("stadium-first:SELF"),"AI chose harmful orientation: "+id+" "+difficulty);s.submit(A,A,decision.revision(),decision.option());AiCardOperationTest.settle(s,difficulty);AiCardOperationTest.finish(s,difficulty);check(m.phase()==MatchPhase.FINISHED,"Directional Stadium AI stalled "+id+" "+difficulty);
    }}
    static void schema(){var registry=EffectRegistry.standard();reject(()->BundledCombatData.trainer(JsonParser.parseString("{\"trainerCategory\":\"ITEM\",\"directionalStadium\":true,\"effects\":[{\"type\":\"draw\",\"target\":\"SELF\",\"amount\":1}]}").getAsJsonObject(),registry));reject(()->BundledCombatData.trainer(JsonParser.parseString("{\"trainerCategory\":\"STADIUM\",\"directionalStadium\":\"true\",\"effects\":[]}").getAsJsonObject(),registry));var m=twoStadiums(DynamicPassiveModifierTest.plainStadium(),profile(PARALLEL));reject(()->m.playTrainer(A,hand(m,A,"stadium").instanceId(),null,A));}
}
